var app=new Vue({el:"#app",delimiters:["[[","]]"],data:{errors:[],newBookText:null,ans:[]},methods:{getData(){const a=window.location.origin+"/dashboard/wordbooks/data";axios.get(a).then(a=>{this.ans=a.data}).catch(a=>{console.log(a)})},addNewBook(){this.newBookText?(this.ans.push({name:this.newBookText,content:[{stype:"text",scontent:""}]}),this.errors=[],this.newBookText=null,this.updatePasive()):this.errors.push("Kh\xF4ng \u0111\u01B0\u1EE3c \u0111\u1EC3 tr\u1ED1ng!")},deleteBook(a){this.ans.splice(a,1),this.updatePasive()},addNewQues(a){this.ans[a].content.push({stype:"text",scontent:""}),this.updatePasive()},deleteQues(a,b){this.ans[a].content.splice(b,1),this.updatePasive()},updateData(){const a=window.location.origin+"/dashboard/wordbooks";axios.post(a,{data:this.ans}).then(a=>{this.$notify({group:"notification",type:a.data.status,title:a.data.title,text:a.data.message,duration:2500,speed:1e3})}).catch(a=>{console.log(a)})},updatePasive(){const a=window.location.origin+"/dashboard/wordbooks";axios.post(a,{data:this.ans}).catch(a=>{console.log(a)})}},computed:{dragOptions(){return{animation:0,group:"description",disabled:!1,ghostClass:"ghost"}}},created(){this.getData()}});